// hinnoittelukenttä kelpaa tyhjänä tai lukuna, joka ei ole negatiivinen; ALV 0–30 %
function arvoOk(v){var n=jasenna(v); return tyhja(v)||(isFinite(n)&&n>=0);}
function alvOk(H){var v=H?H.alv:undefined, n=jasenna(v); return v===undefined||v===null||tyhja(v)||(isFinite(n)&&n>=0&&n<=30);}
// automaattinen tarkka hinta vain, kun kaikki kentät kelpaavat ja €/km ja minimi ovat yli nollan
function onHinnat(h){return !!h&&HKENTAT.every(function(k){return arvoOk(h[k]);})&&num(h.km)>0&&num(h.min)>0;}
function alvp(H){return H&&H.alv!==undefined&&H.alv!==null&&!tyhja(H.alv)&&alvOk(H)?num(H.alv):K.alv;}

/* Laskee hinnan pyynnön tiedoista. Tarkka hinta vain, jos myynti on syöttänyt kokoluokan hinnat
   (lähtömaksu, €/km, €/h, minimi). Muuten Åbergin julkaisema hintataso, jos molemmat päät ovat pikavalintoja. */
function laske(p,H){
 H=H||hinnoittelu(); var n=Math.round(num(p.montako)), r=reitti(p.mista,p.minne), muoto=p.muoto||'kuljetus';
 var tulos={tila:'ei',reitti:r,muoto:muoto,n:n};
 if(!n||!String(p.mista||'').trim()||!String(p.minne||'').trim()){tulos.tila='kesken'; return tulos;}
 var l=luokka(n), autoja=1; if(!l){l=LUOKAT[LUOKAT.length-1]; autoja=Math.ceil(n/l.max);}
 tulos.luokka=l; tulos.autoja=autoja;
 var h=H[l.id];
 if(r&&onHinnat(h)&&alvOk(H)&&muoto!=='monipaiva'&&!(muoto==='paiva'&&!(num(p.kesto)>0))){
  var lahto=num(h.lahto), ekm=num(h.km), eh=num(h.h), mini=num(h.min), suunnat=[];
  if(muoto==='paiva') suunnat=[['Päiväretki',lahto+2*r.km*ekm+num(p.kesto)*eh]];
  else{var yksi=lahto+r.km*ekm+(r.min/60)*eh; suunnat=muoto==='menopaluu'?[['Meno',yksi],['Paluu',yksi]]:[['Kuljetus',yksi]];}
  var summa=0; suunnat=suunnat.map(function(s){var v=Math.round(Math.max(s[1],mini)*autoja); summa+=v; return [s[0],v];});
  // tarkka hinta vain, kun minimi on yli nollan ja summa vähintään minimi; muuten myynti hinnoittelee käsin
  if(mini>0&&summa>=mini){
   var pros=alvp(H), vero=Math.round(summa*pros)/100;
   tulos.tila='tarkka'; tulos.suunnat=suunnat; tulos.alv0=summa; tulos.alvp=pros; tulos.alv=vero; tulos.yht=summa+vero; tulos.hlo=(summa+vero)/n;
   return tulos;}}
 if(r&&n<=60&&muoto!=='monipaiva'){
  // pitkä matka (esim. Tampere): matka ja ajoaika näkyvät, mutta Helsingin hintatasoa ei näytetä
  if(!(seudulla(p.mista)&&seudulla(p.minne))){tulos.pitka=true; return tulos;}
  if(muoto==='paiva'){tulos.tila='taso'; tulos.taso=K.tasot.paiva; return tulos;}
  tulos.tila='taso'; tulos.taso=n<=16?K.tasot.pikku:K.tasot.iso; tulos.perSuunta=muoto==='menopaluu'; return tulos;}
 return tulos;}

function reittiRivi(t,p){if(!t.reitti||!(t.reitti.km>0)) return '';
 return '<p class="ha-reitti"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="18" r="2.5"/><circle cx="18" cy="6" r="2.5"/><path d="M8.5 18H15a3 3 0 0 0 0-6H9a3 3 0 0 1 0-6h6.5"/></svg>'+
  luku(t.reitti.km)+' km, ajoaika noin '+ajoaika(t.reitti.min)+'</p>';}
function ajoaika(min){return kesto(min*60000);}

function hintaHtml(t,p){
 if(t.tila==='kesken') return '<p class="ha-ots">Hintataso</p><p class="ha-pieni" style="color:inherit">'+esc(T.kesken)+'</p>';
 var nopeaP='<p class="ha-pieni">'+esc(nopea(Date.now()))+'.</p>', lahde='<p class="ha-pieni">'+esc(T.reittilahde)+'</p>';
 if(t.tila==='tarkka'){
  var rivit=t.suunnat.length>1?t.suunnat.map(function(s){return '<p class="ha-rivi"><span>'+s[0]+'</span><b>'+eur(s[1])+'</b></p>';}).join(''):'';
  var lisa=p?lisaSyyt(p):[];
  return '<p class="ha-ots">'+(lisa.length?'Päämatkan hinta':'Hinta')+(t.autoja>1?', '+t.autoja+' × '+esc(t.luokka.nimi):'')+'</p>'+rivit+
   '<p class="ha-rivi ha-iso"><span>Yhteensä alv 0 %</span><b>'+eur(t.alv0)+'</b></p>'+
   '<p class="ha-pieni">'+eur(t.yht)+' sis. alv '+luku(t.alvp)+' %, noin '+eur(t.hlo)+' / hlö. '+esc(T.tarkka)+'</p>'+
   (lisa.length?'<p class="ha-pieni" style="color:#fff">'+esc(lisatTxt(lisa))+'</p>':'')+reittiRivi(t,p)+lahde;}
 if(t.tila==='taso') return '<p class="ha-ots">Hintataso</p><p class="ha-rivi"><span>'+esc(t.taso.selite)+(t.perSuunta?', per suunta':'')+'</span><b>'+esc(t.taso.hinta)+'</b></p>'+
  '<p class="ha-pieni">'+esc(T.taso)+(p&&lisaSyyt(p).length?' '+esc(lisatTxt(lisaSyyt(p))):'')+'</p>'+reittiRivi(t,p)+nopeaP+(t.reitti&&t.reitti.km>0?lahde:'');
 var syy=t.n>60?T.yli60:(t.muoto==='monipaiva'?T.monipaiva:t.pitka?T.pitka:T.eiTasoa);
 return '<p class="ha-ots">Hinta tarjouksessa</p><p class="ha-pieni" style="color:#dce4ee">'+esc(syy)+'</p>'+reittiRivi(t,p)+nopeaP+(t.reitti&&t.reitti.km>0?lahde:'');}

function lyhytHinta(t){if(t.tila==='tarkka') return eur(t.yht)+' sis. alv'; if(t.tila==='taso') return t.taso.hinta+(t.perSuunta?' / suunta':''); if(t.tila==='kesken') return '–'; return 'Tarjouksessa';}

/* ---------------------------------------------------------------- yhteiset palat: tila, rivit, sähköposti */
var TILAT={uusi:['Odottaa tarjousta','uusi'],tarjottu:['Tarjous lähetetty','tarjottu'],hyvaksytty:['Hyväksytty','hyvaksytty'],vahvistettu:['Varaus vahvistettu','vahvistettu'],soitto:['Soittopyyntö','soitto'],hoidettu:['Hoidettu','']};
function tilaHtml(p){var t=TILAT[p.tila]||TILAT.uusi; return '<span class="tila'+(t[1]?' tila--'+t[1]:'')+'">'+t[0]+'</span>';}
function reittiTeksti(p){return (p.mista||'?')+' → '+(p.minne||'?')+(p.muoto==='menopaluu'?' ja takaisin':'');}
// käyttötarkoitus: palvelusivu tai nappi kertoo, mihin kuljetus on (urheilu, tapahtuma, häät)
var LAJIT={peli:'Joukkueen pelimatka',kausi:'Kauden kuljetukset',kuljetus:'Tapahtumakuljetus',shuttle:'Shuttle-ajo',lento:'Lentokenttäkuljetus'};
// sivun käyttötarkoitus tulee body-luokasta (konteksti-urheilu), joka säilyy myös WordPress-teemassa
function sivuKonteksti(){var m=/(?:^|\s)konteksti-([a-z]+)/.exec(d.body.className); return m?m[1]:'';}
function kayttoNimi(p){if(p.konteksti==='haat') return 'Hääkuljetus'; return p.konteksti&&LAJIT[p.laji]?LAJIT[p.laji]:'';}
function kausi(p){return p.konteksti==='urheilu'&&p.laji==='kausi';}
function paluullinen(p){return p.muoto==='menopaluu'||p.muoto==='monipaiva';}
// mikä jää laskurin päämatkan ulkopuolelle: näillä hinta lasketaan käsin eikä tarjous lähde automaattisesti
function lisaSyyt(p){var s=[];
 if(p.noudot&&p.noudot.length) s.push(p.noudot.length>1?'lisänoudot':'lisänouto');
 if(kausi(p)) s.push('kauden muut matkat');
 if(p.konteksti==='tapahtuma'&&p.laji==='shuttle') s.push('shuttle-ajo');
 if(p.konteksti==='haat'&&p.useita) s.push('useampi paluulähtö');
 return s;}
function lisatTxt(l){return 'Tarjoukseen lasketaan lisäksi '+l.join(', ')+'.';}
function kasin(p){return !!p.esteeton||lisaSyyt(p).length>0;}
function klo(a){return a?'klo '+a.replace(':','.'):'';}
function muutMatkat(p){return (p.matkat||[]).map(function(m){return [pvm(m.paiva)||'päivä auki',m.kohde||'kohde auki'].join(' ');}).concat(p.ohjelmaAvoin?['otteluohjelma tarkentuu myöhemmin']:[]).join('; ')||'ei vielä tiedossa';}
function rivit(p){
 var perilla=p.aikatapa==='perilla'&&p.aika, r=[['Matka',reittiTeksti(p)]], k=kayttoNimi(p);
 if(k) r.push(['Kuljetus',k]);
 if(p.noudot&&p.noudot.length) r.push([p.noudot.length>1?'Noudot':'Nouto',p.noudot.join(', ')]);
 r.push(['Muoto',MUODOT[p.muoto]||'']);
 r.push(['Lähtö',(pvm(p.paiva)||'sovitaan')+(perilla?', perillä viimeistään '+klo(p.aika):p.aika?' '+klo(p.aika):'')]);
 if(paluullinen(p)) r.push(['Paluu',(pvm(p.paluupaiva)||'sama päivä')+(p.paluuAvoin?', aika ei vielä tiedossa':p.paluuaika?' '+klo(p.paluuaika):'')]);
 if(p.konteksti==='haat'&&p.useita) r.push(['Paluulähdöt',p.paluuajat||'useampi, ajat sovitaan']);
 if(p.muoto==='paiva') r.push(['Kesto',p.kesto?p.kesto+' h':'sovitaan']);
 if(kausi(p)) r.push(['Muut matkat',muutMatkat(p)]);
 if(p.konteksti==='tapahtuma'&&p.laji==='shuttle'&&p.shuttle) r.push(['Ajoaika',p.shuttle]);
 if(p.konteksti==='tapahtuma'&&p.laji==='lento'&&(p.lento||p.saapuu)) r.push(['Lento',[p.lento,p.saapuu?'saapuu '+klo(p.saapuu):''].filter(Boolean).join(', ')]);
 r.push(['Matkustajia',p.montako?p.montako+' hlö':'–']);
 if(p.esteeton) r.push(['Esteettömyys','Ryhmässä pyörätuolin käyttäjä tai muu esteettömyystarve']);
 if(p.toiveAuto) r.push([AUTOT[p.toiveAuto]?'Toivottu koko':'Toivottu bussi',p.toiveAuto]);
 if(p.toiveet&&p.toiveet.length) r.push(['Toiveet',p.toiveet.join(', ')]);
 if(p.lisat) r.push(['Lisätiedot',p.lisat]);
 return r;}
// matkan aikajana: lähtö, noudot, perillä ja paluu samassa järjestyksessä asiakkaalle, myyjälle ja tarjoukseen
var AJAT={'Matka':1,'Nouto':1,'Noudot':1,'Lähtö':1,'Paluu':1,'Paluulähdöt':1};
function muutRivit(p){return rivit(p).filter(function(x){return !AJAT[x[0]];});}
// valmis=true: tarjous tai varaus asiakkaalle. Silloin ei luvata ajoaikojen vahvistusta tarjouksessa (se on jo tässä).
function matkaHtml(p,valmis){return p.mista||p.minne?matkajana(p,valmis)+dl(muutRivit(p)):dl(rivit(p));}
// jokin kellonaika puuttuu: lähtöaika (perillä-aika ei kerro lähtöä), paluuaika tai häiden paluulähtöjen ajat
function ajatAuki(p){if(!p.aika||p.aikatapa==='perilla') return true; if(p.konteksti==='haat'&&p.useita) return !p.paluuajat; return paluullinen(p)&&(p.paluuAvoin||!p.paluuaika);}
function matkajana(p,valmis){var pv=pvm(p.paiva), perilla=p.aikatapa==='perilla', a=[];
 var huom=valmis?(ajatAuki(p)?T.ajatSovitaan:''):(perilla&&p.aika?T.ajatPerilla:T.ajatMyynti);
 a.push(['Lähtö',p.mista,[pv,perilla?'':klo(p.aika)].filter(Boolean).join(' ')]);
 (p.noudot||[]).forEach(function(n){a.push(['Nouto',n,'']);});
 a.push([perilla&&p.aika?'Perillä viimeistään':'Perillä',p.minne,perilla?klo(p.aika):'']);
 if(p.konteksti==='haat'&&p.useita) a.push(['Paluulähdöt',p.minne+' → '+p.mista,p.paluuajat||'ajat sovitaan']);
 else if(paluullinen(p)) a.push(['Paluu',p.minne+' → '+p.mista,[p.paluupaiva&&p.paluupaiva!==p.paiva?pvm(p.paluupaiva):'',p.paluuAvoin?'aika ei vielä tiedossa':klo(p.paluuaika)].filter(Boolean).join(' ')]);
 return '<ol class="matkajana">'+a.map(function(x){return '<li><span class="mj-mita">'+esc(x[0])+'</span><span class="mj-aika">'+esc(x[2])+'</span><span class="mj-paikka">'+esc(x[1]||'?')+'</span></li>';}).join('')+'</ol>'+
  (huom?'<p class="matkajana-huom">'+esc(huom)+'</p>':'');}
// esteettömyystarve ja lisämatkat: myyjä varmistaa kaluston ja hinnan ennen tarjousta, joten laskettua hintaa ei esitäytetä.
// "Laskelma kattaa vain päämatkan" vain, kun laskelma on olemassa (t.tila==='tarkka').
function huomioEsteeton(p,t){var l=lisaSyyt(p);
 return (p.esteeton?'<p class="huomio-esteeton" role="note">'+esc(T.esteetonMyyja)+'</p>':'')+
  (l.length?'<p class="huomio-lisat" role="note">Pyynnössä on '+esc(l.join(', '))+'. '+esc(t&&t.tila==='tarkka'?T.lisatLaskelma:T.lisatKasin)+'</p>':'');}
// miksi hintaa ei laskettu: myyjälle näytettävä syy (reitti puuttuu, monta päivää, kesto puuttuu tai kokoluokalla ei hinnoittelua)
function kasinSyy(p,t,H){if(t.tila==='tarkka') return '';
 if(!t.reitti) return T.eiReittia;
 if(t.muoto==='monipaiva') return T.monipaivaMyyja;
 if(t.muoto==='paiva'&&!(num(p.kesto)>0)) return T.eiKestoa;
 if(t.luokka&&!onHinnat(H[t.luokka.id])) return T.eiHinnoitteluaLuokka;
 if(!alvOk(H)) return T.alvVirheMyyja;
 return T.kasin;}
function ehdotusTaiSyy(p,t,H,luokka){var pa=luokka===''?'<p>':'<p class="erittely">';
 if(t.tila==='tarkka') return pa+ehdotusOts(p)+t.suunnat.map(function(s){return s[0]+' '+eur(s[1]);}).join(', ')+(t.autoja>1?', '+t.autoja+' autoa':'')+' ('+esc(t.luokka.nimi)+(t.reitti?', '+luku(t.reitti.km)+' km':'')+').</p>';
 var nahty=p.hinta&&p.hinta.tila==='taso'&&p.hinta.taso?'Asiakas näki hintatason '+esc(p.hinta.taso.hinta)+(p.hinta.perSuunta?' / suunta':'')+'. ':'';
 return pa+nahty+esc(kasinSyy(p,t,H))+'</p>';}
function ehdotusOts(p){return p.esteeton?'Tavallisen kaluston laskelma, ei esteetön: ':lisaSyyt(p).length?'Laskelma vain päämatkasta: ':'Ehdotus hinnoittelusta: ';}
function dl(r){return '<dl>'+r.map(function(x){return '<dt>'+esc(x[0])+'</dt><dd>'+esc(x[1])+'</dd>';}).join('')+'</dl>';}
function tarjousHinta(p){return p.tarjous||null;}
function hintaRivitDoc(p){var t=tarjousHinta(p);
 if(t){var s=(t.suunnat||[]).length>1?t.suunnat.map(function(x){return '<div><span>'+x[0]+'</span><span>'+eur2(x[1])+'</span></div>';}).join(''):'';
  return '<div class="doc-hinta">'+s+'<div><span>Hinta alv 0 %</span><span>'+eur2(t.alv0)+'</span></div><div><span>Arvonlisävero '+luku(t.alvp)+' %</span><span>'+eur2(t.alv)+'</span></div>'+
   '<div class="yht"><span>Yhteensä</span><span>'+eur2(t.yht)+'</span></div></div>';}
 var h=p.hinta||{};
 if(h.tila==='taso') return '<div class="doc-hinta"><div><span>'+esc(h.taso.selite)+(h.perSuunta?', per suunta':'')+'</span><span>'+esc(h.taso.hinta)+'</span></div></div><p class="doc-huom">'+esc(T.taso)+' '+esc(nopea(p.luotu))+'.</p>';
 return '<p class="doc-huom">'+esc(nopea(p.luotu))+'.</p>';}

// K-20: lähtö tänään tai huomenna: tilausajopäivystyksen numero linkkinä (yhteystiedot-14)
function paivystys(){var n=Y.paivystys||'', s=esc(T.paivystys); return n&&Y.paivystysTel?s.replace(esc(n),'<a href="'+Y.paivystysTel+'">'+esc(n)+'</a>'):s;}
function spostiHtml(p,laji){
 var tarjous=laji==='tarjous', t=tarjousHinta(p), linkki='tarjous-nakyma.html?id='+encodeURIComponent(p.id);
 var aihe=tarjous?'Tarjous '+p.id+': '+reittiTeksti(p)+(p.paiva?', '+pvm(p.paiva):''):'Saimme tarjouspyyntönne '+p.id;
 var tervehdys='Hei'+(etunimi(p.nimi)?' '+esc(etunimi(p.nimi)):'')+',';
 var runko=tarjous?'<p>'+tervehdys+'</p><p>kiitos tarjouspyynnöstä. Tässä tarjouksemme matkastanne.</p>'+
   '<table>'+rivit(p).map(function(x){return '<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td></tr>';}).join('')+
   '<tr><td>Hinta</td><td><b>'+(t?eur2(t.yht)+' sis. alv '+luku(t.alvp)+' %':'')+'</b></td></tr></table>'+
   '<a class="nappi nappi--kelta" href="'+linkki+'"><span>Avaa ja hyväksy tarjous</span></a>'
  :'<p>'+tervehdys+'</p><p>kiitos tarjouspyynnöstä. '+esc(kasittely(p.luotu))+(pian(p.paiva,p.luotu)?' '+paivystys():'')+'</p>'+
   '<table>'+rivit(p).map(function(x){return '<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td></tr>';}).join('')+
   (p.hinta&&p.hinta.tila==='taso'?'<tr><td>Hintataso</td><td>'+esc(p.hinta.taso.hinta)+(p.hinta.perSuunta?' / suunta':'')+'</td></tr>':'')+'</table>'+
   '<a class="nappi nappi--reuna" href="'+linkki+'"><span>Katso pyyntö</span></a>';
 return '<div class="sposti" aria-label="Sähköpostin esikatselu">'+
  '<div class="sposti-paa"><span>Lähettäjä: <b>'+esc(Y.lahettaja)+'</b></span><span>'+(p.sposti||!p.puhelin?'Vastaanottaja':'Tekstiviestinä numeroon')+': <b>'+esc(p.sposti||p.puhelin||'asiakas')+'</b></span><span class="sposti-aihe">'+esc(aihe)+'</span></div>'+
  '<div class="sposti-runko">'+runko+'<p class="allekirjoitus">Ystävällisin terveisin<br>'+esc(Y.allekirjoitus)+'<br>'+esc(Y.puh)+' · '+esc(Y.sposti)+'</p></div></div>'+
  '<p class="demohuom">'+esc(T.demoSposti)+'</p>';}

/* ---------------------------------------------------------------- vastausaika, laskutustiedot ja Y-tunnus */
/* "Jopa parissa tunnissa" on toimiston lupaus, ja toimisto on avoinna arkisin 8–16 (yhteystiedot-13).
   Toimistoajan ulkopuolella asiakkaalle näytetään vain aukioloaika, ja myynnin laskuri laskee kaksi toimistotuntia. */
var LUPAUS=2*3600*1000, AUKI=8, KIINNI=16, LUETUT='ab-luetut';
/* K-20: arkipyhät, jolloin toimisto ei ole "arkisin" auki: uudenvuodenpäivä, loppiainen, pitkäperjantai, 2. pääsiäispäivä, vappu,
   helatorstai, itsenäisyyspäivä ja joulu. Juhannusaatto ja jouluaatto ovat oletus (yleinen käytäntö), varmistetaan Åbergilta. */
var PYHAT={};
function pyhat(v){if(PYHAT[v]) return PYHAT[v];
 var a=v%19, b=Math.floor(v/100), c=v%100, e=b%4, f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3), h=(19*a+b-Math.floor(b/4)-g+15)%30,
  l=(32+2*e+2*Math.floor(c/4)-h-c%4)%7, m=Math.floor((a+11*h+22*l)/451), kk=Math.floor((h+l-7*m+114)/31), pv=(h+l-7*m+114)%31+1;
 var lista={}, lisaa=function(t){lista[t.getMonth()+'-'+t.getDate()]=1;};
 [[0,1],[0,6],[4,1],[11,6],[11,24],[11,25],[11,26]].forEach(function(x){lisaa(new Date(v,x[0],x[1]));});
 [-2,1,39].forEach(function(x){lisaa(new Date(v,kk-1,pv+x));});           // pitkäperjantai, 2. pääsiäispäivä, helatorstai
 for(var j=19;j<=25;j++) if(new Date(v,5,j).getDay()===5) lisaa(new Date(v,5,j)); // juhannusaatto
 return (PYHAT[v]=lista);}
function arkipaiva(t){var v=t.getDay(); return v>0&&v<6&&!pyhat(t.getFullYear())[t.getMonth()+'-'+t.getDate()];}
function toimistoAuki(ts){var t=new Date(ts), h=t.getHours(); return arkipaiva(t)&&h>=AUKI&&h<KIINNI;}
function nopea(ts){return toimistoAuki(ts)?T.nopea:T.toimisto;}
// O-18: milloin toimisto seuraavaksi aukeaa, esim. "to 12.11. klo 8"
function aukeaa(ts){var t=new Date(ts);
 for(var i=0;i<20;i++){var alku=new Date(t); alku.setHours(AUKI,0,0,0); if(arkipaiva(t)&&ts<alku.getTime()) return alku.getTime(); t=alku; t.setDate(t.getDate()+1);}
 return t.getTime();}
function viikonpaiva(ts){var t=new Date(ts); return ['su','ma','ti','ke','to','pe','la'][t.getDay()]+' '+t.getDate()+'.'+(t.getMonth()+1)+'.';}
